-- V44__seed_class10_science_lectures_and_topics.sql
-- Seeds complete, verified 225 topics and video timestamps for Class 10 Science (086)
-- All 13 chapters covered with 100% zero-gap continuous YouTube lecture timestamps.

-- 1. Clean up existing topics & content items for Class 10 Science to prevent duplicates
DELETE FROM learn_content_items
WHERE topic_id IN (
    SELECT t.id FROM learn_topics t
    JOIN learn_chapters c ON t.chapter_id = c.id
    WHERE c.subject_id = '65d29b56-1111-0000-0000-000000000010'
);

DELETE FROM learn_topics
WHERE chapter_id IN (
    SELECT id FROM learn_chapters
    WHERE subject_id = '65d29b56-1111-0000-0000-000000000010'
);

-- 2. Insert verified Class 10 Science Topics (225 Topics)
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, order_index = EXCLUDED.order_index, is_active = EXCLUDED.is_active;

-- 3. Insert verified Class 10 Science Video Content Items (225 Video Items)
ON CONFLICT (id) DO UPDATE SET content_url = EXCLUDED.content_url, is_free = EXCLUDED.is_free, order_index = EXCLUDED.order_index;
